import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';

const mono = { fontFamily: "'JetBrains Mono', monospace" };

const TIER_STYLES = {
  HIGH_CONF: { bg: 'rgba(0,232,122,0.1)',  border: 'rgba(0,232,122,0.4)',  color: '#00e87a', label: '⬡ HIGH CONFIDENCE'           },
  MODERATE:  { bg: 'rgba(245,166,35,0.1)', border: 'rgba(245,166,35,0.4)', color: '#f5a623', label: '◈ MODERATE'                   },
  NEUTRAL:   { bg: 'rgba(90,106,130,0.1)', border: 'rgba(90,106,130,0.4)', color: '#5a6a82', label: '⊘ NEUTRAL — signals conflicting' },
};

const PredictionCard = ({ prediction }) => {
  const {
    ticker, timestamp, current_price, predicted_price,
    direction, change_percent, confidence, regime,
    confidence_tier, top_features,
  } = prediction;

  const isUp      = direction?.includes('UP');
  const isNeutral = confidence_tier === 'NEUTRAL';
  const [confWidth, setConfWidth] = useState(0);

  useEffect(() => {
    const t = setTimeout(() => setConfWidth((confidence || 0.5) * 100), 200);
    return () => clearTimeout(t);
  }, [confidence]);

  const fmt = iso => new Date(iso).toLocaleString('en-US', {
    month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit',
  });

  // SHAP divergence detection
  const shapBullish = top_features?.filter(f => f.impact > 0).length || 0;
  const shapBearish = top_features?.filter(f => f.impact < 0).length || 0;
  const shapTotal   = top_features?.length || 0;
  const shapNet     = shapBullish > shapBearish ? 'bullish' : 'bearish';
  const hasDivergence = shapTotal > 0 && ((shapNet === 'bullish' && !isUp) || (shapNet === 'bearish' && isUp));

  const tier      = TIER_STYLES[confidence_tier] || TIER_STYLES['MODERATE'];
  const regimeName = regime?.regime_name || 'Trending';
  const regimeColor = regimeName === 'Calm' ? '#7cc674' : regimeName === 'Volatile' ? '#ff3b6b' : '#00d2ff';

  // Confidence zone markers
  const thresholds = [
    { pos: 42, label: 'HIGH DN ≤42%', side: 'left'  },
    { pos: 53, label: '',             side: null     },
    { pos: 58, label: 'HIGH UP ≥58%', side: 'right' },
  ];

  return (
    <motion.div
      className="prediction-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45 }}
    >
      {/* Top row: ticker + badge */}
      <div className="pred-top">
        <div>
          <div className="prediction-ticker">{ticker}</div>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginTop: 4 }}>
            <span style={{ fontSize: 12, color: 'var(--dim)' }}>
              {regimeName} regime
            </span>
            {/* Tier badge inline */}
            <span style={{
              ...mono, fontSize: 9, fontWeight: 700,
              color: tier.color, background: tier.bg,
              border: `1px solid ${tier.border}`,
              borderRadius: 3, padding: '1px 8px',
            }}>
              {tier.label}
            </span>
          </div>
          <div className="prediction-timestamp">{fmt(timestamp)}</div>
        </div>

        {/* Direction badge */}
        <div>
          {hasDivergence && (
            <div style={{
              ...mono, fontSize: 9, color: 'var(--amber)',
              background: 'rgba(245,166,35,0.08)',
              border: '1px solid rgba(245,166,35,0.25)',
              borderRadius: 5, padding: '5px 10px',
              maxWidth: 220, lineHeight: 1.5, marginBottom: 8,
            }}>
              ⚠ SHAP features {shapNet} ({shapBullish}/{shapTotal}), ensemble {isUp ? 'UP' : 'DOWN'} — signals split
            </div>
          )}
          <div className={`direction-badge ${isUp ? 'up' : 'down'}`}>
            <span className="dir-arrow">{isUp ? '↑' : '↓'}</span>
            <div>
              <span>{isUp ? 'BULLISH' : 'BEARISH'}</span>
              {hasDivergence && (
                <div style={{ fontSize: 9, marginTop: 2, color: 'var(--amber)', fontWeight: 400 }}>
                  ⚡ SHAP DIVERGENCE
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* 4 price boxes */}
      <div className="prediction-prices">
        {[
          { label: 'Current Price',   val: `$${(current_price || 0).toFixed(2)}`,                           cls: 'current'                          },
          { label: 'Predicted Price', val: `$${(predicted_price || 0).toFixed(2)}`,                         cls: 'predicted'                        },
          { label: 'Expected Change', val: `${(change_percent || 0) >= 0 ? '+' : ''}${(change_percent || 0).toFixed(2)}%`, cls: isUp ? 'up' : 'down'  },
          { label: 'Market Regime',   val: regimeName,                                                       cls: `regime-${regimeName.toLowerCase()}` },
        ].map((b, i) => (
          <motion.div
            key={i} className="price-box"
            initial={{ opacity: 0, x: -16 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.08 * i }}
          >
            <div className="price-label">{b.label}</div>
            <div className={`price-value ${b.cls}`}>{b.val}</div>
          </motion.div>
        ))}
      </div>

      {/* Confidence bar + threshold markers */}
      <div>
        <div className="conf-header">
          <span className="conf-label">Ensemble Composite Score</span>
          <span className="conf-value">{((confidence || 0.5) * 100).toFixed(1)}%</span>
        </div>

        <div className="confidence-progress" style={{ position: 'relative', overflow: 'visible' }}>
          <div className="confidence-fill" style={{ width: `${confWidth}%` }} />
          {thresholds.map((t, i) => (
            <div key={i} style={{
              position: 'absolute', left: `${t.pos}%`, top: -2,
              width: 1, height: 'calc(100% + 4px)',
              background: 'rgba(255,255,255,0.22)', zIndex: 2,
            }} />
          ))}
        </div>

        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 4 }}>
          <span style={{ ...mono, fontSize: 7, color: 'var(--red)', fontWeight: 700 }}>HIGH DN ≤42%</span>
          <span style={{ ...mono, fontSize: 7, color: 'var(--dim)', fontWeight: 700  }}>NEUTRAL 47–53%</span>
          <span style={{ ...mono, fontSize: 7, color: 'var(--green)', fontWeight: 700 }}>HIGH UP ≥58%</span>
        </div>
      </div>

      {/* SHAP divergence detail banner */}
      {hasDivergence && (
        <motion.div
          initial={{ opacity: 0 }} animate={{ opacity: 1 }}
          style={{
            marginTop: 10, padding: '7px 12px', borderRadius: 6,
            background: 'rgba(245,166,35,0.08)', border: '1px solid rgba(245,166,35,0.25)',
            ...mono, fontSize: 10, color: 'var(--amber)', lineHeight: 1.55,
          }}
        >
          ⚠️ SHAP features are predominantly {shapNet} ({shapBullish}/{shapTotal} positive),
          but ensemble direction is {isUp ? 'UP' : 'DOWN'}. SHAP explains the price regression head;
          ensemble incorporates RSI + MACD + MA signals.
        </motion.div>
      )}

      {/* Neutral zone note */}
      {isNeutral && (
        <div style={{
          marginTop: 8, padding: '6px 12px', borderRadius: 5,
          background: 'rgba(90,106,130,0.06)', border: '1px solid rgba(90,106,130,0.2)',
          ...mono, fontSize: 9, color: '#5a6a82', lineHeight: 1.5,
        }}>
          ⚠ NEUTRAL tier — composite in 47–53% zone. Excluded from accuracy metrics.
          Only HIGH_CONF signals (≥58% or ≤42%) carry statistically significant edge.
        </div>
      )}
    </motion.div>
  );
};

export default PredictionCard;
